import itertools,json
jobs="ABCDE"; published="ACEBD"
slot=[[4,8,0,2,0],[6,4,5,0,5],[2,6,4,6,0],[8,7,9,6,0],[3,3,1,6,5]]
transfer=[[0,1,1,3,1],[5,0,2,4,2],[3,1,0,0,3],[5,4,4,0,5],[5,0,3,4,0]]
def nominal(q):
    idx=[jobs.index(x) for x in q]
    return sum(slot[j][i] for i,j in enumerate(idx))+sum(transfer[a][b] for a,b in zip(idx,idx[1:]))
def distance(q):
    perm=[published.index(j) for j in q]
    seen=set(); cycles=0
    for i in range(5):
        if i not in seen:
            cycles+=1
            while i not in seen:
                seen.add(i);i=perm[i]
    return 5-cycles
groups={d:[] for d in range(3)}
for q in map("".join,itertools.permutations(jobs)):
    d=distance(q)
    if d>2 or q.index("A")>q.index("D") or q[1]=="E" or q[4]=="D" or q[2]=="E": continue
    score=nominal(q)+6*max(0,q.index("A")-1)+4*d+(5 if d==2 else 0)
    groups[d].append((score,q))
best=min(x for g in groups.values() for x in g)
answer=dict(roster=best[1],score=best[0],best_by_swaps={str(d):min((x[0] for x in g),default=None) for d,g in groups.items()},feasible_by_swaps={str(d):len(g) for d,g in groups.items()})
print(json.dumps(answer))
# Independently verify minimum distances with breadth-first swap expansion.
dist={published:0}
front={published}
for d in [1,2]:
    new=set()
    for p in front:
        for i,j in itertools.combinations(range(5),2):
            q=list(p);q[i],q[j]=q[j],q[i];q="".join(q)
            if q not in dist: new.add(q)
    for q in new:dist[q]=d
    front=new
assert all(distance(q)==d for q,d in dist.items())
checked={d:[] for d in range(3)}
for q,d in dist.items():
    a=q.index("A")+1;e=q.index("E")+1;dd=q.index("D")+1
    if not (a<dd and e not in (2,3) and dd!=5):continue
    n=sum(slot[ord(j)-65][i] for i,j in enumerate(q))
    n+=sum(transfer[ord(q[i])-65][ord(q[i+1])-65] for i in range(4))
    checked[d].append((n+6*max(a-2,0)+4*d+5*(d==2),q))
assert all(sorted(checked[d])==sorted(groups[d]) for d in groups)
print("BFS cross-check passed")
print("optimal nominal",nominal(best[1]),"distance",distance(best[1]))
print("best by class", {d:sorted(g)[:3] for d,g in groups.items()})

